class Solution {
public:
    bool makesquare(vector<int>& matchsticks) {
        int n = matchsticks.size();
        long long total = 0;
        for (int x : matchsticks) total += x;
        if (total % 4 != 0) return false;
        long long target = total / 4;
        for (int x : matchsticks) if (x > target) return false;
        int full = (1 << n) - 1;
        vector<long long> dp(1 << n, -1);
        dp[0] = 0;
        for (int mask = 0; mask <= full; mask++) {
            if (dp[mask] == -1) continue;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) continue;
                long long next = dp[mask] + matchsticks[i];
                if (next > target) continue;
                dp[mask | (1 << i)] = next % target;
            }
        }
        return dp[full] == 0;
    }
};
